    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.15],
    [235+Math.cos(t*0.32+5)*125, 205+Math.sin(t*0.52)*85, 0.085, 1.95, -0.35],
    [80+Math.sin(t*0.6+3)*70, 50+Math.cos(t*0.7+1)*60, 0.13, 1.3, 0.25],
