  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cr = cross/28;
  const bg1 = (Math.sin(sx*0.038+sy*0.022+t*0.75) + Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
