  const moire = Math.sin(sx*0.2)*Math.sin(sy*0.2)*Math.sin((sx+sy)*0.15+t*0.5)*0.2;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral*0.4 + cr*0.3 + pulse + moire)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.095+t)*0.45 + Math.sin(sx*0.08-t*0.7)*Math.cos(sy*0.1+t*0.5)*0.3)*1.4)*0.25;
  const grain = (Math.sin(sx*0.8+t*5)*Math.sin(sy*0.9-t*4.3)*0.5+Math.sin(sx*1.2-sy*0.7+t*7)*0.3)*0.04;
